/// <summary>
/// VM - CB219 - PO Acknowledgement-update underbond field in METPurchTable.
/// </summary>
[ExtensionOf(formDataSourceStr(PurchCreateOrder, PurchTable))]
final  class METPurchCreateOrderFormPurchTableDS_Extension
{
}

Method.Source:
    /// <summary>
    /// VM - CB219 - PO Acknowledgement-update underbond field in METPurchTable.
    /// </summary>
    void write()
    {
        next write();

        FormCheckBoxControl checkBox = this.formRun().design().controlName(formControlStr(PurchCreateOrder,METUnderBond)) as FormCheckBoxControl;
        PurchTable  purchTableLoc = this.cursor();
        METPurchTable metPurchTable = METPurchTable::find(purchTableLoc.PurchId, true);

        if (metPurchTable)
        {
            ttsbegin;
            metPurchTable.UnderBond = checkBox.value();
            metPurchTable.update();
            ttscommit;
        }
    }
